{
  "cards": {
    "cover": {
      "narration": "Six days, four travellers, one Seoul. The Kimchi Club rolled in on 1 Dec 2026 and made the city its own.",
      "headline": "Seoul"
    },
    "critters": {
      "narration": "Two kinds of critters crossed our path, and one was brand new to us. A proper welcome from the local wildlife."
    },
    "route": {
      "narration": "Myeongdong to Bukchon to Gangnam to Suwon, 96 km of Seoul under our feet and wheels.",
      "line": "The longest hop, Gangnam to Suwon, was 38.4 km and 55 minutes, with Grab at the wheel for 22 of those."
    },
    "awards": {
      "narration": "And now, the Kimchi Club honours. Four travellers, four very well-earned titles."
    },
    "receipt": {
      "narration": "KRW 4,820,000 all in, KRW 1,205,000 each, against a plan of KRW 4,400,000. Over by KRW 420,000, but settled before we even left.",
      "line": "Worth every won for a Hanwoo dinner at KRW 480,000 and a day 5 at KRW 31,000 each."
    },
    "got_away": {
      "narration": "One epic critter stayed shy, zero sightings, but we found 1 of its 4 forms. It comes back every December, so the door is open.",
      "line": "Nobody missed it. It just wasn't ready for us. December will bring another chance."
    },
    "stamp": {
      "narration": "The Kimchi Club stamps Seoul 1–6 Dec 2026 onto the pass. Six days, four friends, one city that now owes us a grilled sardine or two."
    },
    "postcard": {
      "narration": "One last card from Seoul, before we fly home to wherever the sardines are.",
      "line": "Seoul was all neon, kimchi, and long walks. Miss you. Bring the grill."
    }
  },
  "awards": [
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000001",
      "title": "Planner",
      "line": "Ha made 9 plan edits, 75% of the crew's 12."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000002",
      "title": "Navigator",
      "line": "Jun logged all 7 rides, every single one of the crew's 7."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000003",
      "title": "Treasurer",
      "line": "Mia logged 18 of the crew's 40 expenses, 45% of the ledger."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000004",
      "title": "Human Camera",
      "line": "Leo snapped 140 photos, 45% of the crew's 312."
    }
  ]
}
